  function info(text){const d=node('div',undefined,'info-note');d.append(node('span','◎'),node('p',text));return d;}
  function table(headers,rows){const wrap=node('div',undefined,'table-wrap'),t=node('table',undefined,'data-table'),head=node('thead'),hr=node('tr'),body=node('tbody');for(const h of headers)hr.append(node('th',h));head.append(hr);for(const row of rows){const tr=node('tr');for(const value of row){const td=node('td');td.append(value instanceof Node?value:document.createTextNode(value==null?'—':String(value)));tr.append(td);}body.append(tr);}t.append(head,body);wrap.append(t);return wrap;}
  function titleCell(title,sub){const d=node('div');d.append(node('strong',title));if(sub)d.append(node('small',sub));return d;}
