  function count(v){return Number.isFinite(Number(v))?Number(v):0;}
  function fmt(v,digits=2){return Number.isFinite(Number(v))?new Intl.NumberFormat(undefined,{maximumFractionDigits:digits}).format(Number(v)):String(v??'—');}
  function date(value){if(!value)return'No deadline';const d=new Date(value+'T12:00:00');return Number.isNaN(d.getTime())?value:d.toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});}
  function overdue(r){return r.status!=='received'&&r.status!=='closed'&&r.due_date&&r.due_date<new Date().toISOString().slice(0,10);}
  const all = key => Array.isArray(state.overview?.[key])?state.overview[key]:[];
  const contextArray=key=>Array.isArray(state.context?.[key])?state.context[key]:[];
  const selectedCompany=()=>all('companies').find(c=>c.id===state.companyId);
  const companyName=id=>all('companies').find(c=>c.id===id)?.name||'Company';
  const byId=(type,id)=>all(type).find(item=>item.id===id)||contextArray(type).find(item=>item.id===id);
  function periodYear(p){if(!p)return'';const m=String(p.name||'').match(/(?:FY\s*)?(20\d{2})[-–/](\d{2,4})/i);if(m)return m[1]+'-'+m[2].slice(-2);if(p.start){const d=new Date(p.start+'T12:00:00'),y=d.getMonth()>=3?d.getFullYear():d.getFullYear()-1;return y+'-'+String(y+1).slice(-2);}return p.name||'';}
