  function workspaceUrl(view,companyId=state.companyId,year=state.year,tab=null){const q=new URLSearchParams();if(companyId)q.set('company',companyId);if(year)q.set('year',year);if(tab)q.set('tab',tab);return'/boutique'+(q.size?'?'+q:'')+'#'+view;}
  function reportUrl(r){return'/brsr?company='+encodeURIComponent(r.company_id)+(r.id?'&report='+encodeURIComponent(r.id):'');}
  function toolUrl(path){const q=new URLSearchParams();if(state.companyId)q.set('company',state.companyId);return path+(q.size?'?'+q:'');}
  async function api(url,body,method){const options=body===undefined?{}:{method:method||'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)};const r=await fetch(url,options);let data;try{data=await r.json();}catch(_){throw new Error('The server could not return this record. Please try again.');}if(!r.ok){let detail=data.detail;if(Array.isArray(detail))detail=detail.map(d=>d.msg).join('; ');throw new Error(typeof detail==='string'?detail:'Check the form values and try again.');}return data;}
