  function updateUrl(replace=false){const target=workspaceUrl(state.view,state.companyId,state.year,state.view==='data'?state.tab:null);if(location.pathname+location.search+location.hash!==target)history[replace?'replaceState':'pushState']({},'',target);}
  async function chooseCompany(id,view='setup'){state.aiMessages=[];state.aiStatus=null;state.companyId=id;state.periodId='';state.context=null;const years=periods().map(periodYear).filter(Boolean).sort().reverse();if(state.year&&!years.includes(state.year))state.year=years[0]||'';else if(!state.year)state.year=years[0]||'';state.view=view;state.query='';state.filter='';updateUrl();await load();}
  async function selectRecordContext(record,view='data'){state.companyId=record.company_id;state.periodId=record.period_id||'';state.year=periodYear(byId('periods',record.period_id))||state.year;state.view=view;updateUrl();await load();}
  function go(view,options={}){state.view=views.includes(view)?view:'dashboard';if(options.tab)state.tab=options.tab;state.query='';state.filter='';updateUrl();render();window.scrollTo({top:0,behavior:'instant'});if(state.view==='ai')loadAiStatus();if(state.view==='standards')loadCatalog();}
  async function load(){const id=++state.loadId;$('loading').hidden=false;$('view-content').hidden=true;message('page-error');try{state.overview=await api('/api/boutique/overview');if(id!==state.loadId)return;if(state.companyId&&!all('companies').some(c=>c.id===state.companyId&&c.active)){state.companyId='';state.context=null;}const fromPeriod=all('periods').find(p=>p.id===state.periodId);if(fromPeriod){state.companyId=fromPeriod.company_id;state.year=periodYear(fromPeriod);}if(!state.year)state.year=periods().map(periodYear).filter(Boolean).sort().reverse()[0]||'';if(state.companyId){const q=new URLSearchParams({company_id:state.companyId});if(state.year)q.set('year',state.year);if(state.periodId)q.set('period_id',state.periodId);state.context=await api('/api/boutique/company?'+q);if(id!==state.loadId)return;}else state.context=null;updateUrl(true);render();if(state.view==='ai')loadAiStatus();if(state.view==='standards')loadCatalog();}catch(e){message('page-error',e.message);$('view-content').hidden=false;$('view-content').replaceChildren(empty('This workspace could not load.','Your records have not changed. Refresh the workspace to try again.',btn('Try again',load,'button primary')));}finally{if(id===state.loadId)$('loading').hidden=true;}}
  function renderContext(){const c=selectedCompany();$('firm-name').textContent=state.overview?.firm?.name||'Consulting firm';$('breadcrumb-firm').textContent=state.overview?.firm?.name||'Trace AI';$('nav-client-name').textContent=c?.name||'Choose a client to begin';$('client-context').replaceChildren(new Option('All firm clients',''));for(const company of all('companies').filter(c=>c.active))$('client-context').add(new Option(company.name,company.id));$('client-context').value=state.companyId;const years=[...new Set(periods().map(periodYear).filter(Boolean))].sort().reverse();$('year-context').replaceChildren(new Option(c?'Choose a reporting year':'All reporting years',''));for(const year of years)$('year-context').add(new Option('FY '+year,year));$('year-context').value=state.year;$('context-caption').textContent=c?(selectedPeriod()?'Company and reporting year selected':'Choose a reporting year to collect data'):'One portfolio. Connected evidence.';document.querySelectorAll('#client-nav a').forEach(a=>{a.classList.toggle('disabled',!c);a.setAttribute('aria-disabled',String(!c));});const pending=Array.isArray(state.overview.review_queue)?state.overview.review_queue.length:all('datasets').filter(d=>d.status==='submitted').length+all('activities').filter(a=>a.status==='draft').length;$('task-count').hidden=!pending;$('task-count').textContent=String(pending);}
  function render(){if(!state.overview)return;renderContext();if(!views.includes(state.view))state.view='dashboard';const current=copy[state.view];$('breadcrumb-page').textContent=({dashboard:'Firm dashboard',clients:'Client companies',team:'Team & access',standards:'Standards & coefficients',tasks:'Review & tasks',setup:'Company setup',data:'Data & evidence',review:'Review & calculations',reports:'BRSR reports',ai:'Ask Trace AI'})[state.view];$('page-eyebrow').textContent=current[0];$('page-title').textContent=current[1];$('page-description').textContent=current[2];document.querySelectorAll('[data-view]').forEach(a=>{if(a.dataset.view===state.view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('page-actions').replaceChildren(btn('Refresh ↻',load));$('view-content').hidden=false;$('view-content').replaceChildren();if(clientViews.includes(state.view)&&!state.companyId){$('view-content').append(clientGate());return;}({dashboard:renderDashboard,clients:renderClients,team:renderTeam,standards:renderStandards,tasks:renderTasks,setup:renderSetup,data:renderData,review:renderReview,reports:renderReports,ai:renderAi})[state.view]();}
  function clientGate(){return empty('Choose a client company.','Open a company from your portfolio to see its setup, reporting years and connected data.',btn('View client companies →',()=>go('clients'),'button primary'));}
  function yearGate(){const d=node('div',undefined,'year-gate');d.append(node('span','01 · COMPANY SETUP','eyebrow'),node('h2','Give the data a reporting year.'),node('p','Create or select a reporting year first. Datasets, evidence and calculations will stay linked to that period.'),actions(btn('Set up a reporting year →',()=>go('setup'),'button primary')));return d;}
  function addMetric(target,label,value,detail,signal){const d=node('article',undefined,'metric'),top=node('span',label,'metric-label');if(signal)top.append(node('span',signal,'metric-signal'));d.append(top,node('strong',String(value)),node('small',detail));target.append(d);}
  function metricGrid(){return node('div',undefined,'metrics');}
