  function renderClientCards(list){list.replaceChildren();const q=state.query.toLowerCase(),companies=all('companies').filter(c=>[c.name,c.industry,c.country].join(' ').toLowerCase().includes(q));if(!companies.length){list.append(empty('No client companies found.','Try a different search or create a new company.',btn('Add client',()=>editCompany(),'button primary')));return;}for(const c of companies){const d=node('article',undefined,'card client-card'),top=node('div',undefined,'client-topline'),initials=c.name.split(' ').slice(0,2).map(w=>w[0]).join('').toUpperCase(),p=reportProgressFor(c.id);top.append(node('span',initials,'client-monogram'),badge(c.active?'Active client':'Inactive',c.active?'':'draft'));d.append(top,node('h2',c.name),node('p',[c.industry,c.country].filter(Boolean).join(' · ')||'Company profile to complete','company-meta'));const track=node('div',undefined,'progress'),fill=node('span');fill.style.width=Math.min(100,p.percentage)+'%';track.append(fill);const label=node('div',undefined,'progress-label');label.append(node('span',p.label),node('span',p.percentage+'%'));d.append(track,label);const stats=node('div',undefined,'client-stats');for(const [value,text]of [[all('datasets').filter(x=>x.company_id===c.id&&x.status==='missing').length,'Missing datasets'],[all('evidence').filter(x=>x.company_id===c.id).length,'Evidence files'],[all('reports').filter(x=>x.company_id===c.id).length,'BRSR reports']]){const s=node('div');s.append(node('strong',String(value)),node('span',text));stats.append(s);}d.append(stats);const open=btn('Open workspace →',()=>chooseCompany(c.id),'text-button');open.disabled=!c.active;d.append(actions(open,btn('Edit profile',()=>editCompany(c),'text-button')));list.append(d);}}
