  function field(key,label,options={}){return{key,label,...options};}
  let formHandler=null,formInputs={};
  function openForm(title,intro,fields,handler,submit='Save record'){ $('form-title').textContent=title;$('form-intro').textContent=intro;$('form-submit').textContent=submit;$('form-fields').replaceChildren();message('form-error');formInputs={};for(const f of fields){const label=node('label',undefined,'form-field'+(f.wide?' wide':'')+(f.type==='checkbox'?' checkbox-field':''));let input;if(f.type==='select'||f.type==='multi'){input=node('select');if(f.type==='multi'){input.multiple=true;input.size=Math.min(5,Math.max(2,(f.options||[]).length));}for(const option of f.options||[])input.add(new Option(option.label??option[1],option.value??option[0]));if(f.type==='multi'){for(const option of input.options)option.selected=(f.value||[]).includes(option.value);}else{if(f.value&&!Array.from(input.options).some(o=>o.value===String(f.value)))input.add(new Option(String(f.value),String(f.value)));input.value=f.value??'';}}else if(f.type==='textarea'){input=node('textarea');input.rows=f.rows||3;input.value=f.value??'';}else{input=node('input');input.type=f.type||'text';if(f.type==='checkbox')input.checked=Boolean(f.value);else if(f.type!=='file')input.value=f.value??'';}input.id='form-'+f.key;input.name=f.key;input.required=Boolean(f.required);if(f.maxLength)input.maxLength=f.maxLength;if(f.placeholder)input.placeholder=f.placeholder;if(f.accept)input.accept=f.accept;if(f.min!=null)input.min=f.min;if(f.max!=null)input.max=f.max;if(f.step)input.step=f.step;formInputs[f.key]=input;if(f.type==='checkbox')label.append(input,node('span',f.label));else label.append(node('span',f.label),input);if(f.help)label.append(node('small',f.help));$('form-fields').append(label);}formHandler=handler;$('form-dialog').showModal();}
  function values(){const out={};for(const [key,input]of Object.entries(formInputs)){out[key]=input.type==='checkbox'?input.checked:input.type==='file'?input.files[0]:input.multiple?[...input.selectedOptions].map(o=>o.value):input.value.trim();}return out;}
  async function saved(text='Saved. Your workspace is up to date.'){await load();message('page-feedback',text);}
